// Independent exhaustive verification of the manuscript's placement recurrence.
package main
import("encoding/json";"fmt";"math";"math/rand";"kubeedgeinfer/internal/partition")
func main(){ rng:=rand.New(rand.NewSource(20261004)); checks:=0; maxerr:=0.0
 for trial:=0;trial<1000;trial++{n:=1+rng.Intn(8);w:=1+rng.Intn(4);c:=.1+10*rng.Float64();in:=partition.Input{TotalLayers:n,PerLayerMs:c,EmbedMs:20*rng.Float64(),HeadMs:80*rng.Float64()};for i:=0;i<w;i++{in.Workers=append(in.Workers,partition.Worker{Speed:1.5*rng.Float64()});if i>0{in.LinkMs=append(in.LinkMs,100*rng.Float64())}}
 for _,o:=range []partition.Objective{partition.ObjectiveLatency,partition.ObjectiveThroughput}{best:=math.Inf(1);var visit func(int,int,float64);visit=func(i,a int,v float64){if i==w{if a==n && v<best{best=v};return};for b:=a;b<=n;b++{d:=0.0;if b>a{d=float64(b-a)*c;if a==0{d+=in.EmbedMs};if b==n{d+=in.HeadMs};d/=math.Max(.01,in.Workers[i].Speed);if i>0{d+=in.LinkMs[i-1]}};next:=math.Max(v,d);if o==partition.ObjectiveLatency{next=v+d};visit(i+1,b,next)}};visit(0,0,0);got,e:=partition.OptimalForObjective(in,o);if e!=nil{panic(e)};value:=got.BottleneckMs;if o==partition.ObjectiveLatency{value=got.PipelineMs};err:=math.Abs(value-best);maxerr=math.Max(maxerr,err);if err>1e-8*math.Max(1,best){panic(fmt.Sprintf("trial %d objective %s: %g != %g",trial,o,value,best))};checks++}}
 b,_:=json.MarshalIndent(map[string]interface{}{"seed":20261004,"random_inputs":1000,"objective_checks":checks,"layers_range":[]int{1,8},"workers_range":[]int{1,4},"maximum_absolute_difference_ms":maxerr,"scope":"independent exhaustive cost evaluation; no runtime performance claim"},"","  ");fmt.Println(string(b))}
